// GetXID
$$$TRACE("Get person_xid for VisitID: " _ VisitID)
set tSc = ..CallQuery("select top 1 PersonXID from person_xid (nolock) where regsystem not like '%302' and id in " _
				" (select patientid from visit (nolock) where id= '" _ VisitID _ "')", .resStr)
set pResponse.PersonXID	= resStr


// GetProviderCode
$$$TRACE("GetProviderCode for BillingProviderID: " _ BillingProviderID)
set pResponse.ProviderEC = ""
if ($E(BillingProviderID,1,2) = "OE")
{
	 set BillingProviderID = "0"
}


set tSc = ..CallQuery("select EntryCode from Provider (NoLock) where  (ID = '" _ BillingProviderID_ "')", .resStr)
set pResponse.ProviderEC	= resStr

