return tSc

	$$$TRACE("Inside CallStoredProc, call: " _ procName _ " EventSequenceID: " _ req.EventSequenceID)

	#dim tSC As %Status=$$$OK
	#dim tRTs As %ListOfObjects
	#dim tResultSet,snap As EnsLib.SQL.Snapshot
	Set snap=##class(EnsLib.SQL.Snapshot).%New()
	Set snap.MaxRowsToGet=-1
	Set tRTs=##class(%Library.ListOfObjects).%New()
	Set tOutParms=##class(%Library.ListOfObjects).%New()

	Do tRTs.Insert(snap)

	set ioParms=numParam
	// Input - 11
	Do ..CopyIoParms(.ioParms, req)

	// Output
	For i=12:1:ioParms {
		set ioParms(i,"SqlType")= 12
	}

	// tQuery
	set quesStr = ""
	For i=1:1:ioParms-1 {
		set quesStr = quesStr _ "?,"
	}
	set quesStr = quesStr _ "?"
	Set tQuery="{call " _ procName _ "(" _ quesStr _ ")}"

	// pIO
	set pIOStr = ""
	set quesStr = ""
	For i=1:1:11 {
		set pIOStr = pIOStr _ "i"
	}
	For i=12:1:ioParms {
		set pIOStr = pIOStr _ "o"
	}
	set pIOStr = pIOStr _ "#"


	$$$TRACE("Call Stored Procedure " _ tQuery _ "; " _ pIOStr)
	Set tSC = ..Adapter.ExecuteProcedureParmArray(.tRTs,.tOutParms,tQuery,pIOStr,.ioParms)
  	$$$TRACE("Stored Procedure " _ procName _ " status "_tSC) 
  	if $$$ISOK(tSC)
  	{
  		If $ISOBJECT(tOutParms) 
  		{

	  		$$$TRACE("Successfully Called proc, outparm cnt  :"_tOutParms.Count())	
	  		/*
	  		For i=1:1:tOutParms.Count() {
  					$$$TRACE(i _ ". " _ procName _ " Output: " _ tOutParms.GetAt(i))
			}
	  		*/	
  		}
  	}
  	else
  	{
	  	$$$LOGERROR("Error in calling stored Proc: " _ procName _ " = " _  tSC)
  	}

   quit tSC

	$$$TRACE("Call ExecuteQuery " _ queryStr )
	Set tSC = ..Adapter.ExecuteQuery(.tResult, queryStr)
  	//Get the result
   If tResult.Next() {
     Set tOutParms = tResult.GetData(1)
   } Else {
   //Handle no phone number for example
     Set tOutParms = ""
   }
   $$$TRACE("Query output: " _ tOutParms )
   Quit tSC

set SqlType = 0
IF ( (type = "varchar") || (type = "name") || (type = "xml"))
{
	set SqlType = $$$SqlVarchar
}
ELSEIF  ($FIND(type, "uniqueidentifier") > 1)
{
	set SqlType = $$$SqlLongVarBinary
}
ELSEIF  ($FIND(type, "id") > 1)
{
	set SqlType = $$$SqlNumeric
}


ELSEIF  (($FIND(type, "code") > 1)
		|| ($FIND(type, "char") > 1)
		|| ($FIND(type, "BOOL") > 1)
		|| ($FIND(type, "message") > 1)
		|| ($FIND(type, "extension") > 1)
		)
{
	set SqlType = $$$SqlChar
}
ELSEIF ($FIND(type, "smallint") > 1) //New
{
	set SqlType = $$$SqlSmallint
}
ELSEIF ($FIND(type, "int_phone") > 1) //New
{
	set SqlType = $$$SqlVarchar
}
ELSEIF ($FIND(type, "tinyint") > 1) //New
{
	set SqlType = $$$SqlTinyint
}
ELSEIF ($FIND(type, "int") > 1)
{
	set SqlType = $$$SqlInteger
}
ELSEIF ($FIND(type, "decimal") > 1)
{
	set SqlType = $$$SqlDecimal
}
ELSEIF ($FIND(type, "numeric") > 1)
{
	set SqlType = $$$SqlNumeric
}
ELSEIF ($FIND(type, "datetimestamp") > 1)
{
	set SqlType = $$$SqlTypeTimestamp
}
ELSEIF ($FIND(type, "datetime") > 1)
{
	set SqlType = $$$SqlDateTime
}

else
{
	$$$LOGERROR("  *** In ELSE: " _ name _ ", SET to VARCHAR 12, type:" _ type)
	set SqlType = $$$SqlVarchar
}

if ($FIND(name,"DirectIDs") > 1) // New
{
	set SqlType = $$$SqlUnknownType
}



return SqlType

	// Create the query to return sql code
	set tQuery = "{ ?= call " _ pRequest.ProcName _ " (" 
	set numOut = 1
	set numIn = 0
	set valueArr = pRequest.MyProp.Count() + 1
	set valueArr(1)=""
	set valueArr(1,"SqlType")=$$$SqlInteger
	set pIOStr = "b"

	for i = 1:1:pRequest.MyProp.Count()
	{
		if (pRequest.MyProp.GetAt(i).IsOutput)
		{
			set pIOStr = pIOStr _ "b"
			set numOut = numOut + 1
			$$$TRACE(i _ ". Set output for: " _ pRequest.MyProp.GetAt(i).Name)
		}
		else
		{
			set pIOStr = pIOStr _ "i"
			set numIn = numIn + 1
		} 

		if (i < pRequest.MyProp.Count())
		{
			set tQuery=tQuery _ "?,"
		}
		else
		{
			// End of Query
			set tQuery=tQuery  _ "?)}"
			set pIOStr = pIOStr _ "#"
		}

		if ( $L(pRequest.MyProp.GetAt(i).Value) <= 0)
		{

				set valueArr(i+1)=""

		}
		else
		{
			set valueArr(i+1) = pRequest.MyProp.GetAt(i).Value

		}

		//$$$TRACE("$$$$$$Name: "_ pRequest.MyProp.GetAt(i).Name_" Type: "_ pRequest.MyProp.GetAt(i).Type)
		set valueArr(i+1,"SqlType")= ..GetSqlType(pRequest.MyProp.GetAt(i).Name, pRequest.MyProp.GetAt(i).Type)

		if (valueArr(i+1,"SqlType") = 9) 
		{
				$$$TRACE("Reset value for " _ valueArr(i+1,"SqlType")) 
				if ($L(valueArr(i+1)) = 10)
		          	{
		                    set valueArr(i+1) = valueArr(i+1) _ " 00:00:00:000"
			        }
				elseif ($L(valueArr(i+1)) = 16)
			        {
		                    set valueArr(i+1) = valueArr(i+1) _ ":00:000"
			        }
				elseif ($L(valueArr(i+1)) = 19)
			        {
		                    set valueArr(i+1) = valueArr(i+1) _ ":000"
			        }
			}


		$$$TRACE(i _ ". set: " _ pRequest.MyProp.GetAt(i).Name _ " to '" _ valueArr(i+1) _"', Type: " _ valueArr(i+1,"SqlType"))
		/****
		if ((pRequest.MyProp.GetAt(i).Name = "MessageContent") &&( valueArr(i+1) [ "InterfaceErrorReceivedEvent"))
		{
			  // Output the data to a file
        		Set file=##class(%File).%New("/tmp/InterfaceErrorReceivedEvent " _ $ZH _ ".txt")	
				Do file.Open("WN")
				Do file.WriteLine(valueArr(i+1))
				Do file.Close()

				$$$TRACE("Created a file with InterfaceErrorReceivedEvent data")
		}
		****/
}
	$$$TRACE(valueArr _ ": " _ tQuery)	
	$$$TRACE(pIOStr _ ", # of inputs: " _ numIn _ ", outputs: " _ numOut)
